void draw_background_tiles(void)
{
    int tile_x;
    int tile_y;
    struct BobFrameMetrics *tile_descriptor;
    tile_y = 16;
    while (tile_y < vga_state.screen_height) {
        tile_x = 0;
        while (tile_x < vga_state.screen_width) {
            tile_descriptor = (struct BobFrameMetrics *)(tile_art_base + background_tile_offsets[2 * tileid]);
            draw_bob_sprite_entry((unsigned char *)tile_descriptor, tile_x, tile_y);
            tile_x += tile_descriptor->width;
        }
        tile_y += tile_descriptor->height;
    }
}

void get_sprite_bounds(struct IntRect *bounds, struct BobFrameMetrics *frame_info)
{
    sprite_metadata = frame_info;
    read_sprite_frame_bounds();
    bounds->left += x_delta;
    bounds->top += y_offset;
    bounds->right = bounds->left + width - 2;
    bounds->bottom = bounds->top + height - 2;
}

void get_sprite_collision_bounds(struct IntRect *bounds, struct BobFrameMetrics *frame_info)
{
    sprite_metadata = frame_info;
    read_sprite_frame_bounds();
    bounds->left += x_delta + 3;
    bounds->top += y_offset + 3;
    bounds->right = bounds->left - 3 + width - 5;
    bounds->bottom = bounds->top - 3 + height - 5;
}

#define KEY_SCAN_MOUSE_SENSITIVITY 0x20
#define MOUSE_BUTTON_LOWER_SENSITIVITY 1
#define MOUSE_BUTTON_RAISE_SENSITIVITY 2
#define MOUSE_SENSITIVITY_STEP 2

/* Button clicks change the mouse driver's horizontal and vertical sensitivity. */
void adjust(void)
{
    if (scan_code_bitmap[1].bytes.hi & KEY_SCAN_MOUSE_SENSITIVITY) {
        if (mouse_btn != mouse_btn_old) {
            if (mouse_btn == MOUSE_BUTTON_LOWER_SENSITIVITY) {
                query_mouse_sensitivity();
                x_cursor_sensitivity -= MOUSE_SENSITIVITY_STEP;
                mouse_sensitivity_y_axis -= MOUSE_SENSITIVITY_STEP;
                restore_mouse_driver_sensitivity();
            } else if (mouse_btn == MOUSE_BUTTON_RAISE_SENSITIVITY) {
                query_mouse_sensitivity();
                x_cursor_sensitivity += MOUSE_SENSITIVITY_STEP;
                mouse_sensitivity_y_axis += MOUSE_SENSITIVITY_STEP;
                restore_mouse_driver_sensitivity();
            }
        }
    }
}
